    @Test
    public void testGenerateIdsGeneratesMonotonicallyIncreasingIdsAsync()
            throws Exception {
        final var ids = new byte[100000][];
        for (int index = 0; index < 100000; index++) {
            if (index % 10000 == 0) {
                Thread.sleep(1);
            }
            ids[index] = UInt128.id();
        }
        for (int index = 1; index < ids.length; index++) {
            assertTrue(UInt128.asBigInteger(ids[index - 1])
                    .compareTo(UInt128.asBigInteger(ids[index])) < 0);
        }
    }

