    @Test
    public void testLookupAccountsRoundTripsAllFieldsAsync()
            throws Exception {
        final var accountId = UInt128.id();
        final var userData128 = UInt128.id();
        {
            final var accountBatch = new AccountBatch(1);
            accountBatch.add();
            accountBatch.setId(accountId);
            accountBatch.setLedger(7);
            accountBatch.setCode(42);
            accountBatch.setUserData128(userData128);
            accountBatch.setUserData64(9999999999L);
            accountBatch.setUserData32(12345);
            accountBatch.setFlags(AccountFlags.HISTORY);
            client.createAccountsAsync(accountBatch).get();
        }
        final AccountBatch accounts;
        {
            final var idBatch = new IdBatch(1);
            idBatch.add(accountId);
            accounts = client.lookupAccountsAsync(idBatch).get();
        }
        assertEquals(1, accounts.getLength());
        assertTrue(accounts.next());
        assertArrayEquals(accountId, accounts.getId());
        assertEquals(BigInteger.valueOf(0L), accounts.getDebitsPending());
        assertEquals(BigInteger.valueOf(0L), accounts.getDebitsPosted());
        assertEquals(BigInteger.valueOf(0L), accounts.getCreditsPending());
        assertEquals(BigInteger.valueOf(0L), accounts.getCreditsPosted());
        assertEquals(7, accounts.getLedger());
        assertEquals(42, accounts.getCode());
        assertArrayEquals(userData128, accounts.getUserData128());
        assertEquals(9999999999L, accounts.getUserData64());
        assertEquals(12345, accounts.getUserData32());
        assertEquals(AccountFlags.HISTORY, accounts.getFlags());
        accounts.beforeFirst();
        assertTrue(accounts.next());
        assertTrue(accounts.getTimestamp() > 0L);
    }

